  // 균열 (파괴 진행 10단계): 중앙에서 뻗어 나가는 무작위 선\n  var path = [], seen = {};\n  for (var w = 0; w < 4; w++) {\n    var px = 7 + ((rnd() * 3) | 0) - 1, py = 7 + ((rnd() * 3) | 0) - 1;\n    for (var st = 0; st < 22; st++) {\n      var key = px + ',' + py;\n      if (!seen[key]) { seen[key] = 1; path.push([px, py]); }\n      var r = rnd();\n      if (r < 0.34) px += 1; else if (r < 0.67) px -= 1; else py += (rnd() < 0.5 ? 1 : -1);\n      if (rnd() < 0.5) py += (rnd() < 0.5 ? 1 : -1);\n      px = clamp(px, 0, 15); py = clamp(py, 0, 15);\n    }\n  }\n  for (var s = 0; s < 10; s++) {\n    var cnt = Math.ceil(path.length * (s + 1) / 10);\n    for (var yy = 0; yy < T; yy++) for (var xx = 0; xx < T; xx++) put(T_CRACK + s, xx, yy, 0, 0, 0, 0);\n    for (var i2 = 0; i2 < cnt; i2++) put(T_CRACK + s, path[i2][0], path[i2][1], 12, 12, 12, 235);\n  }\n}\nbuildAtlas();\n\nvar atlasCanvas = document.createElement('canvas');\natlasCanvas.width = atlasCanvas.height = ATLAS_S;\n(function () {\n  var c = atlasCanvas.getContext('2d'), img = c.createImageData(ATLAS_S, ATLAS_S);\n  img.data.set(atlasData); c.putImageData(img, 0, 0);\n})();\n\n// 타일 UV (반 텍셀 안쪽으로 줄여 번짐 방지)\nvar TU = [], TV = [], TW = 1 / ATLAS_N - 1 / ATLAS_S;\nfor (var ti = 0; ti < ATLAS_N * ATLAS_N; ti++) { TU[ti] = (ti % ATLAS_N) / ATLAS_N + 0.5 / ATLAS_S; TV[ti] = ((ti / ATLAS_N) | 0) / ATLAS_N + 0.5 / ATLAS_S; }\n\n/* ======================================================================\n *  지형 생성\n * ==================================================================== */\nfunction heightAt(x, z) {\n  var c = fbm2(x * 0.006, z * 0.006, 0, 3);\n  var h = fbm2(x * 0.02, z * 0.02, 100, 4);\n  var m = Math.max(0, fbm2(x * 0.009, z * 0.009, 200, 3) - 0.5) * 2.6;\n  var y = 2.5 + c * 24 + h * 15 + m * m * 52;\n  if (y > 46) y = 46 + (y - 46) * 0.55;   // 정상이 높이 제한에서 평평하게 잘리지 않도록 압축\n  return clamp(Math.floor(y), 3, CH - 8);\n}\nfunction tempAt(x, z) { return fbm2(x * 0.004, z * 0.004, 300, 2); }\n// 표면 종류: 0 잔디, 1 모래, 2 눈, 3 바위\nfunction surfaceOf(h, t) {\n  if (h <= SEA + 1) return 1;\n  if (t > 0.6 && h < SEA + 16) return 1;\n  if (h >= 46 || (t < 0.34 && h > SEA + 6)) return 2;\n  if (h >= 41) return 3;\n  return 0;\n}\nfunction isCave(x, y, z) {\n  var a = noise3(x * 0.05, y * 0.07, z * 0.05, 400);\n  if (Math.abs(a - 0.5) > 0.05) return false;\n  var b = noise3(x * 0.05, y * 0.07, z * 0.05, 500);\n  return Math.abs(b - 0.5) < 0.05;\n}\nfunction treeAt(wx, wz, h, surf) { return surf === 0 && h > SEA + 1 && h < 40 && hash2(wx, wz, SEED + 99) < 0.012; }\n\nvar world = { chunks: new Map(), edits: new Map() };\n// 차원: 0 = 오버월드, 1 = 엔드. 블록 편집 기록은 차원마다 따로 가진다.\nvar dim = 0, overEdits = world.edits, endEdits = new Map();\nvar END_TOP = 36, END_R = 40;\n// 진행 상태 (모두 저장됨)\nvar pearlTotal = 0, eyeMade = 0;\nvar portalActive = false, visitedEnd = false, crystalsCleared = false, dragonDefeated = false, questIdx = 0, retPos = null;\nvar dragonHp = 120, crystalMask = 255;\nvar fireballs = [];\nfunction ckey(cx, cz) { return (cx + 32768) * 65536 + (cz + 32768); }\nfunction cidx(x, y, z) { return (y * CS + z) * CS + x; }\n\nfunction genChunk(cx, cz) {\n  if (dim === 1) return genChunkEnd(cx, cz);\n  var data = new Uint8Array(CS * CH * CS), x0 = cx * CS, z0 = cz * CS, M = 3, W = CS + 2 * M;\n  var hm = new Int16Array(W * W), tm = new Float32Array(W * W), maxY = 0;\n  for (var j = 0; j < W; j++) for (var i = 0; i < W; i++) {\n    hm[j * W + i] = heightAt(x0 + i - M, z0 + j - M);\n    tm[j * W + i] = tempAt(x0 + i - M, z0 + j - M);\n  }\n  for (var z = 0; z < CS; z++) for (var x = 0; x < CS; x++) {\n    var wx = x0 + x, wz = z0 + z, hi = (z + M) * W + x + M, h = hm[hi], surf = surfaceOf(h, tm[hi]);\n    for (var y = 0; y <= h; y++) {\n      var b;\n      if (y === 0) b = BEDROCK;\n      else if (y === h) b = surf === 0 ? GRASS : surf === 1 ? SAND : surf === 2 ? SNOW : STONE;\n      else if (y >= h - 3) b = surf === 1 ? SAND : surf === 3 ? STONE : DIRT;\n      else {\n        b = STONE;\n        var r = hash